// Macro generates the syscall wrapper function:
// _syscallX(return_type, name, type1, arg1, type2, arg2, ...)

// Example 1: Zero arguments
typedef int pid_t;
_syscall0(pid_t, getpid)

pid_t process_id = getpid();


// Example 2: One argument
_syscall1(void, exit, int, status)

exit(0);


// Example 3: Three arguments (Standard I/O)
typedef long ssize_t;
typedef unsigned long size_t;

_syscall3(ssize_t, read, 
          int, fd, 
          char *, buf, 
          size_t, count)

char buffer[50];
ssize_t result = read(0, buffer, 50);
